resp = <Response [403 Forbidden]>, domain = 'z-library.ec'

    def decode_eapi_json(resp: httpx.Response, domain: str) -> dict:
        """Parse an /eapi response as JSON, classifying anti-bot walls explicitly.

        A healthy EAPI endpoint returns HTTP 200 with JSON. DiamWall-fronted
        domains return a 307 self-redirect, 403/513/517 "Access Denied", or an
        HTML block page — this raises DiamWallError for those so callers see
        "anti-bot wall" instead of a bare JSONDecodeError or status error.
        """
        if resp.status_code == 200:
            try:
                payload = resp.json()
                if _auth_rejected(payload):
                    raise EAPIAuthenticationError(
                        "EAPI authentication rejected",
                        status_code=resp.status_code,
                        token=sanitized_auth_token(payload.get("error")),
                    )
                return payload
            except ValueError:
                pass  # fall through to wall classification
        body = resp.text
        if "diamwall" in body.lower():
            error = _diamwall_error(domain, f"HTTP {resp.status_code} DiamWall block page")
            error.status_code = resp.status_code
            raise error
        if resp.status_code == 401:
            try:
                payload = resp.json()
            except ValueError:
                payload = None
            token = sanitized_auth_token(
                payload.get("error") if isinstance(payload, dict) else None
            )
            raise EAPIAuthenticationError(
                "EAPI authentication rejected", status_code=401, token=token
            )
        if resp.status_code == 400:
            try:
                payload = resp.json()
                if _auth_rejected(payload):
                    raise EAPIAuthenticationError(
                        "EAPI authentication rejected",
                        status_code=400,
                        token=sanitized_auth_token(payload.get("error")),
                    )
            except ValueError:
                pass
        if resp.status_code in WALLED_STATUS_CODES:
            error = _diamwall_error(domain, f"HTTP {resp.status_code}")
            error.status_code = resp.status_code
>           raise error
